export type BotDifficulty = 'easy' | 'medium' | 'hard';

export interface VirtualProfile {
  id: string;
  name: string;
  country: string;
  flag: string;
  level: number;
  rating: number;
  coins: number;
  difficulty: BotDifficulty;
}

export interface MatchedOpponent<TReal = Record<string, unknown>> {
  isVirtual: boolean;
  profile: VirtualProfile | TReal;
}

export interface FindMatchOptions<TReal = Record<string, unknown>> {
  /** Délai d'attente en millisecondes avant de basculer sur un profil virtuel (par défaut 4000 ms) */
  fallbackDelayMs?: number;
  /** Fonction qui recherche un joueur réel */
  searchRealPlayer: (signal: AbortSignal) => Promise<TReal | null>;
  /** ID d'un profil virtuel à exclure éventuellement */
  excludeBotId?: string;
}

