export function getRandomVirtualProfile(excludeId?: string): VirtualProfile {
  const pool = excludeId
    ? VIRTUAL_PROFILES.filter((profile) => profile.id !== excludeId)
    : VIRTUAL_PROFILES;
  const source = pool.length > 0 ? pool : VIRTUAL_PROFILES;
  const randomIndex = Math.floor(Math.random() * source.length);
  return source[randomIndex];
}

export function getVirtualProfileById(id: string): VirtualProfile | undefined {
  return VIRTUAL_PROFILES.find((profile) => profile.id === id);
}

export function isVirtualProfileOrBot(id?: string | null): boolean {
  if (!id) return false;
  return id.startsWith('bot_') || VIRTUAL_PROFILES.some((profile) => profile.id === id);
}

/**
 * Recherche d'abord un joueur réel pendant `fallbackDelayMs` (4000 ms par défaut, borné entre 3000 et 5000 ms).
 * Si aucun joueur réel n'est trouvé avant la fin du délai, sélectionne un profil virtuel.
 */
export async function findOpponentWithFallback<TReal = Record<string, unknown>>({
  fallbackDelayMs = 4000,
  searchRealPlayer,
  excludeBotId,
}: FindMatchOptions<TReal>): Promise<MatchedOpponent<TReal>> {
  const delay = Math.min(5000, Math.max(3000, fallbackDelayMs));
  const controller = new AbortController();
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  try {
    const realPlayerPromise = searchRealPlayer(controller.signal);
    const timeoutPromise = new Promise<null>((resolve) => {
      timeoutId = setTimeout(() => {
        resolve(null);
      }, delay);
    });

    const realPlayer = await Promise.race([realPlayerPromise, timeoutPromise]);

    if (realPlayer) {
      if (timeoutId) clearTimeout(timeoutId);
      return {
        isVirtual: false,
        profile: realPlayer,
      };
    }

    controller.abort();
    const virtualBot = getRandomVirtualProfile(excludeBotId);
    return {
      isVirtual: true,
      profile: virtualBot,
    };
  } finally {
    if (timeoutId) clearTimeout(timeoutId);
  }
}
